SELECT DISTINCT rr_member_id
	, mobile_no
	, email
	, CASE
		WHEN date_part_year(transaction_month) = 2026 THEN TRUE
		ELSE FALSE
	END has_txn_2026
FROM "trusted".rr_turtle_member
ORDER BY 4 DESC, 1


SELECT member_id
	, member_uuid
	, register_datetime
	, registration_source
	, email
	, mobile_no
	, member_type
	, member_status
	, activated_wallet
	, first_app_launch_datetime
FROM refined.dim_hook_member
--WHERE member_id = '14692749'
--WHERE email = '090b95a9231643a8905bcb7cefeac55f6e00788f1b454742525007a1f16a4bfc'
--	OR mobile_no = 'e85fd2d7eb9989c673ec7ba5a4dfa921'



	SELECT member_id
		, member_uuid
		, register_datetime
		, registration_source
		, 'email' AS key_type
		, email AS key_val
	FROM refined.dim_hook_member
	WHERE email IS NOT NULL AND email <> ''
	UNION ALL
	SELECT member_id
		, member_uuid
		, register_datetime
		, registration_source
		, 'mobile' AS key_type
		, mobile_no AS key_val
	FROM refined.dim_hook_member
	WHERE mobile_no IS NOT NULL AND mobile_no <> ''



