),
match_raw AS (
	SELECT e.email_hashed
		, e.mobile_hashed
		, d.member_id
		, d.member_uuid
		, d.register_datetime
		, d.registration_source
		, 1 AS is_email_match
		, 0 AS is_mobile_match
	FROM ex_rr e
	INNER JOIN refined.dim_hook_member d ON e.email_hashed = d.email
	UNION ALL
	SELECT e.email_hashed
		, e.mobile_hashed
		, d.member_id
		, d.member_uuid
		, d.register_datetime
		, d.registration_source
		, 0 AS is_email_match
		, 1 AS is_mobile_match
	FROM ex_rr e
	INNER JOIN refined.dim_hook_member d ON e.mobile_hashed = d.mobile_no
)
, match_agg AS (
	SELECT email_hashed
		, mobile_hashed
		, member_id
		, member_uuid
		, register_datetime
		, registration_source
		, MAX(is_email_match) AS is_email_match
		, MAX(is_mobile_match) AS is_mobile_match
	FROM match_raw
	GROUP BY 1, 2, 3, 4, 5, 6
)
SELECT e.email_hashed
	, e.mobile_hashed
	, e.has_1_txn
	, m.member_id
	, m.member_uuid
	, m.register_datetime
	, m.registration_source
	, CASE
		WHEN m.is_email_match = 1 AND m.is_mobile_match = 1 THEN 'Email & Mobile'
		WHEN m.is_email_match = 1 THEN 'Email only'
		WHEN m.is_mobile_match = 1 THEN 'Mobile only'
		ELSE 'Not found'
	END AS match_type
FROM ex_rr e
LEFT JOIN match_agg m ON e.email_hashed = m.email_hashed AND e.mobile_hashed = m.mobile_hashed
ORDER BY e.email_hashed, e.mobile_hashed, m.register_datetime